s.BadRequest(new{message="Delivery order ke liye customer name, phone aur address lazmi hain."});if(type=="Delivery"){if(!riderId.HasValue)return Results.BadRequest(new{message="Delivery order ke liye available rider select karein."});assignedRider=await db.ServicePeople.FirstOrDefaultAsync(x=>x.Id==riderId&&x.Type=="Rider"&&x.IsActive);if(assignedRider is null)return Results.BadRequest(new{message="Selected rider available nahi hai."});if(await db.Orders.AnyAsync(x=>x.RiderId==riderId&&x.Status!="Completed"&&x.Status!="Cancelled"&&x.Status!="Ready"))return Results.BadRequest(new{message=$"{assignedRider.Name} already booked hai."});}if(type=="Dine-in"){if(!tableId.HasValue)return Results.BadRequest(new{message="Dine-in order ke liye table select karein."});assignedTable=await db.CafeTables.FirstOrDefaultAsync(x=>x.Id==tableId&&x.IsActive);if(assignedTable is null)return Results.BadRequest(new{message="Selected table available nahi hai."});if(await db.Orders.AnyAsync(x=>x.TableId==tableId&&x.Status!="Completed"&&x.Status!="Cancelled"))return Results.BadRequest(new{message=$"{assignedTable.Name} already booked hai."});if(!waiterId.HasValue)return Results.BadRequest(new{message="Dine-in order ke liye available waiter select karein."});assignedWaiter=await db.ServicePeople.FirstOrDefaultAsync(x=>x.Id==waiterId&&x.Type=="Waiter"&&x.IsActive);if(assignedWaiter is null)return Results.BadRequest(new{message="Selected waiter available nahi hai."});if(await db.Orders.AnyAsync(x=>x.WaiterId==waiterId&&x.Status!="Completed"&&x.Status!="Cancelled"))return Results.BadRequest(new{message=$"{assignedWaiter.Name} already booked hai."});}var ids=r.Items.Select(x=>x.VariantId).Distinct().ToList();var variants=await db.ProductVariants.Include(x=>x.Product).Where(x=>ids.Contains(x.Id)&&x.Product!.IsActive&&x.Product.IsAvailable).ToDictionaryAsync(x=>x.Id);if(variants.Count!=ids.Count)return Results.BadRequest(new{message="One or more items are unavailable."});var now=DateTimeOffset.Now