ng(x=>x.CreatedAt).Take(Math.Clamp(take,1,10000)).Select(OrderView.From)));api.MapPut("/orders/{id:long}/status",async(long id,StatusRequest r,PosDb db)=>{var o=await db.Orders.FindAsync(id);if(o is null)return Results.NotFound();var allowed=o.OrderType=="Delivery"?new[]{"New","Preparing","Ready","Completed","Cancelled"}:new[]{"New","Ready","Completed","Cancelled"};if(!allowed.Contains(r.Status))return Results.BadRequest(new{message="This status is not valid for the selected order mode."});if(r.Status=="Completed"&&o.PaymentStatus!="Paid")return Results.Conflict(new{requiresPayment=true,message="Payment required before order completion."});if(r.Status=="Cancelled"&&o.PaymentStatus=="Paid")return Results.Conflict(new{message="Paid order ko cancel karne se pehle Refund/Void workflow required hai."});o.Status=r.Status;o.KitchenStatus=r.Status switch{"New"=>"Pending","Preparing"=>"Preparing","Ready"=>"Ready","Completed"=>"Served","Cancelled"=>"Cancelled",_=>o.KitchenStatus};await db.SaveChangesAsync();return Results.Ok(new{o.Id,o.Status,o.KitchenStatus,o.PaymentStatus});});api.MapGet("/dashboard",async(PosDb db)=>{var all=await db.Orders.Include(x=>x.Items).AsNoTracking().ToListAsync();var os=all.Where(x=>x.CreatedAt.LocalDateTime.Date==DateTime.Now.Date&&x.Status!="Cancelled").ToList();var paid=os.Where(x=>x.PaymentStatus=="Paid").ToList();var active=os.Count(x=>x.Status is "New" or "Preparing" or "Ready");var outstanding=os.Where(x=>x.PaymentStatus!="Paid").Sum(x=>x.Total);return Results.Ok(new{sales=paid.Sum(x=>x.Total),orderCount=active,bookedOrders=active,paidOrders=paid.Count,outstanding,averageOrder=outstanding,cashSales=paid.Where(x=>x.PaymentMethod=="Cash").Sum(x=>x.Total),activeOrders=active,topItems=paid.SelectMany(x=>x.Items).GroupBy(x=>x.ProductName).Select(g=>new{name=g.Key,quantity=g.Sum(x=>x.Quantity),sales=g.Sum(x=>x.LineTotal)}).OrderByDescending(x=>x.quantity).Take(5)});});api.MapGet("/insights",async(PosDb db)=>{var valid=(await db.Orders.Include(x=>x.Items).AsNoTracking().ToListAsync()).Where(x=>x.Status!="Cancelled"&&x.PaymentStatus=="Paid").ToList();var sales=valid.SelectMany(x=>x.Items).GroupBy(x=>x.ProductName).ToDictionary(g=>g.Key,g=>new{quantity=g.Sum(x=>x.Quantity),sales=g.Sum(x=>x.LineTotal)});var names=await db.Products.Where(x=>x.IsActive).Select(x=>x.Name).ToListAsync();var products=names.Select(n=>new{name=n,quantity=sales.TryGetValue(n,out var a)?a.quantity:0,sales=sales.TryGetValue(n,out var b)?b.sales:0}).ToList();return Results.Ok(new{peakHours=valid.GroupBy(x=>x.CreatedAt.LocalDateTime.Hour).Select(g=>new{hour=g.Key,orders=g.Count(),sales=g.Sum(x=>x.Total)}).OrderByDescending(x=>x.orders),bestItems=products.OrderByDescending(x=>x.quantity).Take(8),slowItems=products.OrderBy(x=>x.quantity).Take(8)});}).RequireAuthorization(p=>p.RequireRole("Admin"));api.MapGet("/customers",async(PosDb db)=>Results.Ok((await db.Customers.Include(x=>x.Orders).ThenInclude(x=>x.Items).AsNoTracking().ToListAsync()).Select(c=>{var os=c.Orders.Where(o=>o.Status!="Cancelled"&&o.PaymentStatus=="Paid").ToList();var fav=os.SelectMany(o=>o.Items).GroupBy(i=>i.ProductName).OrderByDescending(g=>g.Sum(x=>x.Quantity)).FirstOrDefault();return new{c.Id,c.Name,c.Phone,c.Address,c.CreatedAt,c.LastSeenAt,orderCount=os.Count,totalSpent=os.Sum(o=>o.Total),averageOrder=os.Count==0?0:os.Average(o=>o.Total),favouriteItem=fav?.Key};}).OrderByDescending(x=>x.LastSeenAt))).RequireAuthorization(p=>p.RequireRole("Admin"));api.MapGet("/customers/{id:int}",async(int id,PosDb db)=>{var c=await db.Customers.Include(x=>x.Orders).ThenInclude(x=>x.Items).SingleOrDefaultAsync(x=>x.Id==id);if(c is null)return Results.NotFound();return Results.Ok(new{c.Id,c.Name,c.Phone,c.Address,c.CreatedAt,c.LastSeenAt,favourites=c.Orders.Where(x=>x.Status!="Cancelled"&&x.PaymentStatus=="Paid").SelectMany(x=>x.Items).GroupBy(x=>x.ProductName).Select(g=>new{name=g.Key,quantity=g.Sum(x=>x.Quantity),sales=g.Sum(x=>x.LineTotal)}).OrderByDescending(x=>x.quantity).Take(5),orders=c.Orders.OrderByDescending(x=>x.CreatedAt).Select(OrderView.From)});}).RequireAuthorization(p=>p.RequireRole("Admin"));api.MapGet("/backup/status",()=>Results.Ok(new{count=Directory.GetFiles(Path.Combine(dataRoot,"Backups"),"*.db").Length})).RequireAuthorization(p=>p.RequireRole("Admin"));api.MapPost("/backup",async(PosDb db)=>{await db.Database.ExecuteSqlRawAsync("PRAGMA wal_checkpoint(FULL);");var path=Path.Combine(dataRoot,"Backups",$"mnahels-pos-{DateTime.Now:yyyyMMdd-HHmmss}.db");await using var source=new SqliteConnection(connectionString);await using var target=new SqliteConnection($"Data Source={path}");await source.OpenAsync();await target.OpenAsync();source.BackupDatabase(target);return Results.File(path,"application/octet-stream",Path.GetFileName(path));}).RequireAuthorization(p=>p.RequireRole("Admin"));app.MapFallbackToFile("index.html");app.Run();
