class PosDb(DbContextOptions<PosDb> o):DbContext(o){public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<Category> Categories=>Set<Category>();public DbSet<Product> Products=>Set<Product>();public DbSet<ProductVariant> ProductVariants=>Set<ProductVariant>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderItem> OrderItems=>Set<OrderItem>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();public DbSet<Customer> Customers=>Set<Customer>();public DbSet<ServicePerson> ServicePeople=>Set<ServicePerson>();public DbSet<CafeTable> CafeTables=>Set<CafeTable>();protected override void OnModelCreating(ModelBuilder m){m.Entity<AppUser>().HasIndex(x=>x.Username).IsUnique();m.Entity<Customer>().HasIndex(x=>x.Phone).IsUnique();m.Entity<ServicePerson>().HasIndex(x=>new{x.Type,x.Phone}).IsUnique();m.Entity<CafeTable>().HasIndex(x=>x.Name).IsUnique();m.Entity<Order>().HasOne(x=>x.Customer).WithMany(x=>x.Orders).HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.SetNull);}}
class AppUser{public int Id{get;set;}public string Username{get;set;}="";public string DisplayName{get;set;}="";public string Role{get;set;}="Cashier";public string PasswordHash{get;set;}="";public bool IsActive{get;set;}=true;}class Category{public int Id{get;set;}public string Name{get;set;}="";public string Icon{get;set;}="🍽️";public int SortOrder{get;set;}public List<Product> Products{get;set;}=[];}class Product{public int Id{get;set;}public int CategoryId{get;set;}public Category? Category{get;set;}public string Name{get;set;}="";public string? Icon{get;set;}public string? Description{get;set;}public bool IsActive{get;set;}=true;public bool IsAvailable{get;set;}=true;public List<ProductVariant> Variants{get;set;}=[];}class ProductVariant{public int Id{get;set;}public int ProductId{get;set;}public Product? Product{get;set;}public string Name{get;set;}="Regular";public decimal Price{get;set;}public int SortOrder{get;set;}}class Customer{public int Id{get;set;}public string Name{get;set;}="";public string Phone{get;set;}="";public string? Address{get;set;}public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.Now;public DateTimeOffset LastSeenAt{get;set;}=DateTimeOffset.Now;public List<Order> Orders{get;set;}=[];}class Order{public long Id{get;set;}public string ReceiptNumber{get;set;}="";public int TokenNumber{get;set;}public string OrderType{get;set;}="Takeaway";public string PaymentMethod{get;set;}="";public string PaymentStatus{get;set;}="Paid";public string? PaymentReference{get;set;}public DateTimeOffset? PaidAt{get;set;}public string? PaidBy{get;set;}public string CashierName{get;set;}="";public string Status{get;set;}="New";public string KitchenStatus{get;set;}="Pending";public decimal Subtotal{get;set;}public decimal Discount{get;set;}public decimal Total{get;set;}public string? Notes{get;set;}public DateTimeOffset CreatedAt{get;set;}public int? CustomerId{get;set;}public Customer? Customer{get;set;}public string? CustomerName{get;set;}public string? CustomerPhone{get;set;}public string? DeliveryAddress{get;set;}public int? TableNumber{get;set;}public int? TableId{get;set;}public string? TableName{get;set;}public int? RiderId{get;set;}public string? RiderName{get;set;}public int? WaiterId{get;set;}public string? WaiterName{get;set;}public decimal? CashReceived{get;set;}public decimal ChangeDue{get;set;}public List<OrderItem> Items{get;set;}=[];}class OrderItem{public long Id{get;set;}public long OrderId{get;set;}public Order? Order{get;set;}public string ProductName{get;set;}="";public string VariantName{get;set;}="";public int Quantity{get;set;}public decimal UnitPrice{get;set;}public decimal LineTotal{get;set;}public string? Notes{get;set;}}class AuditLog{public long Id{get;set;}public int UserId{get;set;}public string Action{get;set;}="";public string Details{get;set;}="";public DateTimeOffset CreatedAt{get;set;}=DateTimeOffset.Now;}static class CustomerPhone{public static string Normalize(string? v)=>new((v??"").Where(char.IsDigit).ToArray());}static class SchemaUpgrade
{
    public static void Apply(PosDb db)
    {
        db.Database.ExecuteSqlRaw("CREATE TABLE IF NOT EXISTS \"Customers\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_Customers\" PRIMARY KEY AUTOINCREMENT, \"Name\" TEXT NOT NULL, \"Phone\" TEXT NOT NULL, \"Address\" TEXT NULL, \"CreatedAt\" TEXT NOT NULL, \"LastSeenAt\" TEXT NOT NULL);");
        db.Database.ExecuteSqlRaw("CREATE TABLE IF NOT EXISTS \"ServicePeople\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_ServicePeople\" PRIMARY KEY AUTOINCREMENT, \"Type\" TEXT NOT NULL, \"Name\" TEXT NOT NULL, \"Phone\" TEXT NOT NULL, \"IsActive\" INTEGER NOT NULL DEFAULT 1);");
        db.Database.ExecuteSqlRaw("CREATE TABLE IF NOT EXISTS \"CafeTables\" (\"Id\" INTEGER NOT NULL CONSTRAINT \"PK_CafeTables\" PRIMARY KEY AUTOINCREMENT, \"Name\" TEXT NOT NULL, \"IsActive\" INTEGER NOT NULL DEFAULT 1);");
        db.Database.ExecuteSqlRaw("CREATE UNIQUE INDEX IF NOT EXISTS \"IX_ServicePeople_Type_Phone\" ON \"ServicePeople\" (\"Type\",\"Phone\");");
        db.Database.ExecuteSqlRaw("CREATE UNIQUE INDEX IF NOT EXISTS \"IX_CafeTables_Name\" ON \"CafeTables\" (\"Name\");");

        var orderColumns = Columns(db, "Orders");
        AddColumnIfMissing(db, orderColumns, "Orders", "CustomerId", "INTEGER NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "CustomerName", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "CustomerPhone", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "DeliveryAddress", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "TableNumber", "INTEGER NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "TableId", "INTEGER NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "TableName", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "RiderId", "INTEGER NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "RiderName", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "WaiterId", "INTEGER NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "WaiterName", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "CashReceived", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "ChangeDue", "TEXT NOT NULL DEFAULT '0'");
        AddColumnIfMissing(db, orderColumns, "Orders", "PaymentStatus", "TEXT NOT NULL DEFAULT 'Paid'");
        AddColumnIfMissing(db, orderColumns, "Orders", "PaymentReference", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "PaidAt", "TEXT NULL");
        AddColumnIfMissing(db, orderColumns, "Orders", "PaidBy", "TEXT NULL");

        var productColumns = Columns(db, "Products");
        AddColumnIfMissing(db, productColumns, "Products", "Icon", "TEXT NULL");

        db.Database.ExecuteSqlRaw("UPDATE \"Orders\" SET \"TableId\"=\"TableNumber\" WHERE \"TableId\" IS NULL AND \"TableNumber\" IS NOT NULL;");
        db.Database.ExecuteSqlRaw("UPDATE \"Orders\" SET \"PaymentStatus\"='Paid' WHERE \"PaymentStatus\" IS NULL OR TRIM(\"PaymentStatus\")='';");
    }

    private static HashSet<string> Columns(PosDb db, string table)
    {
        var columns = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var connection = db.Database.GetDbConnection();
        var shouldClose = connection.State == System.Data.ConnectionState.Closed;
        if (shouldClose) connection.Open();
        try
        {
            using var command = connection.CreateCommand();
            command.CommandText = $"PRAGMA table_info(\"{table}\");";
            using var reader = command.ExecuteReader();
            while (reader.Read()) columns.Add(reader.GetString(1));
        }
        finally
        {
            if (shouldClose) connection.Close();
        }
        return columns;
    }

    private static void AddColumnIfMissing(PosDb db, HashSet<string> columns, string table, string column, string definition)
    {
        if (!columns.Add(column)) return;
        db.Database.ExecuteSqlRaw($"ALTER TABLE \"{table}\" ADD COLUMN \"{column}\" {definition};");
    }
}
static class PasswordHash{public static string Create(string p){var s=RandomNumberGenerator.GetBytes(16);var h=Rfc2898DeriveBytes.Pbkdf2(p,s,120000,HashAlgorithmName.SHA256,32);return $"{Convert.ToBase64String(s)}.{Convert.ToBase64String(h)}";}public static bool Verify(string p,string stored){var x=stored.Split('.');if(x.Length!=2)return false;return CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(x[1]),Rfc2898DeriveBytes.Pbkdf2(p,Convert.FromBase64String(x[0]),120000,HashAlgorithmName.SHA256,32));}}
